import STCORE as c

RULES=(
 ('EMPIRICAL RULE: 68 / 95 / 99.7',
  'APPROXIMATELY NORMAL ONLY: ABOUT 68%, 95%, 99.7% LIE WITHIN 1, 2, 3 SD OF THE MEAN. OUTSIDE=100%-INSIDE; EACH SYMMETRIC TAIL=OUTSIDE/2. NOT A RULE FOR EVERY DATA SET.'),
 ('RANGE RULE: USUAL / UNUSUAL',
  'USUAL RANGE: MEAN +/- 2 SD. VALUES BELOW/ABOVE ARE UNUSUALLY LOW/HIGH. CHECK WHETHER THE QUESTION INCLUDES THE BOUNDARIES AS UNUSUAL. ABOUT 95% WITHIN ONLY FOR BELL-SHAPED DATA. THIS IS NOT THE IQR OUTLIER RULE.'),
 ('IQR / BOXPLOT OUTLIERS',
  'IQR=Q3-Q1. FENCES: Q1-1.5*IQR AND Q3+1.5*IQR. OUTLIERS ARE STRICTLY OUTSIDE; ON A FENCE IS NOT AN OUTLIER. MODIFIED WHISKERS END AT ACTUAL NON-OUTLIER VALUES. AN OUTLIER IS NOT AUTOMATICALLY AN ERROR.'),
 ('5% INDEPENDENCE RULE',
  'RANDOM SAMPLING WITHOUT REPLACEMENT IS DEPENDENT. IF n<=0.05*N, APPROXIMATE INDEPENDENCE IS OFTEN ACCEPTABLE. OTHERWISE CONSIDER AN EXACT FINITE-POPULATION METHOD. SE CORRECTION: sqrt((N-n)/(N-1)), FOR N>1. WITH REPLACEMENT, DRAWS CAN BE INDEPENDENT.'),
 ('CLT / SAMPLE MEANS',
  'FOR INDEPENDENT DRAWS: mu_xbar=mu; sigma_xbar=sigma/sqrt(n). NORMAL POPULATION: NORMAL x-bar FOR ANY n. OTHERWISE LARGE n SUPPORTS AN APPROXIMATION; n>=30 IS A RULE OF THUMB, NOT A GUARANTEE FOR EXTREME SKEW OR HEAVY TAILS. CLT DOES NOT MAKE INDIVIDUAL X NORMAL.'),
 ('SAMPLE PROPORTION CONDITIONS',
  'p-hat=X/n. INDEPENDENT TRIALS: MEAN=p; SE=sqrt(p*(1-p)/n). NORMAL APPROXIMATION: np>=10 AND n*(1-p)>=10. FOR CONFIDENCE INTERVALS USE p-hat IN THESE COUNTS. FAILED CHECKS: USE EXACT BINOMIAL, OR HYPERGEOMETRIC FOR RANDOM SAMPLING WITHOUT REPLACEMENT.'),
 ('CHOOSE z OR t',
  'PROPORTION INTERVAL: z, IF NORMAL CONDITIONS HOLD. MEAN INTERVAL: KNOWN POPULATION sigma USE z; UNKNOWN sigma ESTIMATED BY s USE t. ONE-SAMPLE OR PAIRED t: df=n-1 (n=NUMBER OF PAIRS FOR PAIRED DATA). TWO-SAMPLE df NEEDS THE APPROPRIATE METHOD. t DOES NOT FIX A SMALL NONNORMAL SAMPLE.'),
 ('CRITICAL VALUE / TAIL AREAS',
  'TWO-SIDED CONFIDENCE C: alpha=1-C; EACH TAIL=alpha/2; UPPER LEFT AREA=(1+C)/2. ONE-SIDED alpha: UPPER LEFT AREA=1-alpha; LOWER LEFT AREA=alpha. TWO-SIDED CUTS ARE +/- THE POSITIVE CRITICAL VALUE. HOME 13=z*; HOME 14=t*.'),
 ('BINOMIAL REQUIREMENTS',
  'FIXED NUMBER n OF TRIALS; TWO OUTCOMES PER TRIAL; SAME SUCCESS PROBABILITY p; INDEPENDENT TRIALS. SUCCESS IS THE OUTCOME COUNTED, NOT NECESSARILY GOOD. mu=np; VAR=np*(1-p); SD=sqrt(VAR). WITHOUT REPLACEMENT, HYPERGEOMETRIC IS THE EXACT MODEL.'),
 ('PROBABILITY: OR / AND / GIVEN',
  'OR: P(A OR B)=P(A)+P(B)-P(A AND B). MUTUALLY EXCLUSIVE: OVERLAP=0. AND: P(A AND B)=P(A)*P(B GIVEN A); IF INDEPENDENT USE P(A)*P(B). GIVEN: P(A GIVEN B)=P(A AND B)/P(B), IF P(B)>0. COMPLEMENT: P(NOT A)=1-P(A).'),
 ('DISCRETE / CONTINUOUS EVENTS',
  'DISCRETE: ADD P OF MATCHING VALUES; < AND <= CAN DIFFER. FOR INTEGER COUNTS, X<k MEANS X<=k-1 WHEN k IS INTEGER. CONTINUOUS: P(X=k)=0, SO ENDPOINT INCLUSION DOES NOT CHANGE AREA. KEEP THE ORIGINAL CUTOFF BEFORE CONVERTING p-hat TO X=n*p-hat.'),
 ('POPULATION sigma VS SAMPLE s',
  'MEAN=SUM(x)/COUNT. SUM SQUARED DEVIATIONS=SUM((x-MEAN)^2). POPULATION VARIANCE DIVIDES BY N; SAMPLE VARIANCE DIVIDES BY n-1. SD=SQRT(VARIANCE). EQUALLY LIKELY DIGITS 0..9: mu=4.5; VAR=8.25; sigma=sqrt(8.25). THE SAMPLE SIZE 800 IS USED LATER IN sigma/sqrt(800).'),
 ('CONFIDENCE INTERVAL / MOE',
  'INTERVAL=ESTIMATE +/- CRITICAL*SE. MARGIN E=(UPPER-LOWER)/2; ESTIMATE=(UPPER+LOWER)/2. THE CONFIDENCE LEVEL DESCRIBES LONG-RUN COVERAGE OF THE PROCEDURE. IT IS NOT THE PERCENT OF INDIVIDUAL OBSERVATIONS IN THE INTERVAL. GREATER CONFIDENCE WIDENS THE INTERVAL, OTHER INPUTS FIXED.'),
 ('SAMPLE SIZE / ROUNDING',
  'REQUIRED n: ALWAYS ROUND UP. MEAN: n=(z*SD/E)^2. PROPORTION: n=z*^2*p*(1-p)/E^2; UNKNOWN p USE 0.5. KEEP UNROUNDED INTERMEDIATE VALUES. FOR FIXED CONFIDENCE AND VARIABILITY, QUADRUPLING n HALVES SE AND MARGIN OF ERROR.'),
 ('LAW OF LARGE NUMBERS',
  'WITH INDEPENDENT TRIALS HAVING THE SAME p, RELATIVE FREQUENCY APPROACHES p AS THE NUMBER OF TRIALS GROWS. A LOSING STREAK DOES NOT MAKE A WIN DUE. LLN CONCERNS STABILITY OF AN AVERAGE; CLT CONCERNS ITS SAMPLING-DISTRIBUTION SHAPE.'),
 ('SIGNIFICANCE / DECISION RULE',
  'IF p-VALUE<=alpha, REJECT THE NULL HYPOTHESIS. OTHERWISE FAIL TO REJECT; THIS DOES NOT PROVE THE NULL TRUE. STATISTICAL SIGNIFICANCE DOES NOT IMPLY PRACTICAL IMPORTANCE. A ONE-SIDED ALTERNATIVE USES ITS STATED TAIL; A TWO-SIDED ALTERNATIVE USES BOTH TAILS.')
)

FORMULAS=(
 ('START: WHAT IS ASKED?',
  'PROBABILITY: FIND AN AREA OR CHANCE FOR X, x-bar, SUM OR p-hat. INTERVAL: ESTIMATE AN UNKNOWN POPULATION PARAMETER FROM SAMPLE DATA. SAMPLE SIZE: FIND HOW MANY OBSERVATIONS FOR CONFIDENCE C AND MARGIN E. IDENTIFY THE RANDOM VARIABLE BEFORE CHOOSING SD OR SE.'),
 ('SAMPLE MEAN PROBABILITY',
  'WORDS: AVERAGE / MEAN OF n OBSERVATIONS. USE x-bar, NOT INDIVIDUAL X. CENTER=mu; SE=sigma/sqrt(n); z=(CUTOFF-mu)/SE. INDEPENDENT DRAWS; NORMAL POPULATION OR JUSTIFIED CLT APPROXIMATION. HOME 9 > 2. ENTER POPULATION sigma, NOT SE; PROGRAM DIVIDES BY sqrt(n).'),
 ('SAMPLE SUM PROBABILITY',
  'WORDS: TOTAL / COMBINED SUM OF n OBSERVATIONS. S=SUM(X). INDEPENDENT DRAWS: MEAN=n*mu; SD=sqrt(n)*sigma; z=(SUM CUTOFF-n*mu)/(sqrt(n)*sigma). SAME NORMAL / CLT CONDITIONS AS SAMPLE MEANS. HOME 9 > 2: DIVIDE EACH TOTAL CUTOFF BY n AND SOLVE FOR x-bar=S/n. KEEP ORIGINAL mu,sigma,n.'),
 ('SAMPLE PROPORTION PROBABILITY',
  'WORDS: FRACTION / PERCENT OF A SAMPLE HAVING AN EVENT. p-hat=X/n. CENTER=p; SE=sqrt(p*(1-p)/n); z=(CUTOFF-p)/SE. INDEPENDENCE AND np>=10, n*(1-p)>=10 FOR NORMAL APPROXIMATION. HOME 9 > 4; USE PROPORTION CUTOFFS, NOT COUNTS. SMALL COUNTS: EXACT BINOMIAL; WITHOUT REPLACEMENT: HYPERGEOMETRIC.'),
 ('MEAN CI: sigma KNOWN',
  'WORDS: ESTIMATE POPULATION MEAN; POPULATION SD sigma GIVEN. x-bar +/- z* sigma/sqrt(n). RANDOM, INDEPENDENT SAMPLE; NORMAL POPULATION OR JUSTIFIED LARGE-SAMPLE APPROXIMATION. HOME 11 > 6 > 2 COMPUTES z* AND E FROM sigma,n,C; THEN HOME 11 > 7 > 2 USES x-bar AND E. s IS NOT KNOWN POPULATION sigma.'),
 ('MEAN CI: sigma UNKNOWN',
  'WORDS: ESTIMATE POPULATION MEAN USING SAMPLE SD s. x-bar +/- t* s/sqrt(n); df=n-1. RANDOM, INDEPENDENT SAMPLE; APPROXIMATELY NORMAL POPULATION FOR SMALL n, WITH NO STRONG SKEW OR EXTREME OUTLIERS. HOME 11 > 3. A LARGE n ALONE DOES NOT MAKE sigma KNOWN.'),
 ('PROPORTION CONFIDENCE INTERVAL',
  'WORDS: ESTIMATE POPULATION PERCENT / PROPORTION. p-hat=x/n; p-hat +/- z* sqrt(p-hat*(1-p-hat)/n). RANDOMNESS / INDEPENDENCE; CHECK x>=10 AND n-x>=10 FOR THIS NORMAL INTERVAL. HOME 11 > 1 FOR x,n OR > 2 FOR p-hat,n. USE SAMPLE p-hat, NOT AN UNRELATED POPULATION p.'),
 ('SAMPLE SIZE: MEAN',
  'WORDS: HOW MANY FOR AN AVERAGE WITH MARGIN E AND CONFIDENCE C? n=(z* sigma/E)^2; ROUND UP. IF ONLY PILOT s IS GIVEN, USE IT AS AN ESTIMATE: PLANNING RESULT IS APPROXIMATE. HOME 10 > 2. E AND SD MUST USE THE SAME UNITS.'),
 ('SAMPLE SIZE: PROPORTION',
  'WORDS: HOW MANY TO ESTIMATE A PERCENT WITH MARGIN E? n=z*^2*p0*(1-p0)/E^2; ROUND UP. p0 IS A PRIOR / PLANNING ESTIMATE; UNKNOWN p0 USE 0.5. HOME 10 > 1. ENTER A 5-PERCENTAGE-POINT MARGIN AS 5% OR 0.05, NOT 5.'),
 ('INDIVIDUAL NORMAL PROBABILITY',
  'WORDS: ONE PERSON / ITEM / MEASUREMENT, NOT AN AVERAGE. z=(x-mu)/sigma. DO NOT DIVIDE sigma BY sqrt(n) JUST BECAUSE THE STORY MENTIONS A GROUP. NEED A NORMAL POPULATION MODEL. HOME 5 > 8 > 1. EXPECTED NUMBER IN A GROUP=N*P(EVENT).'),
 ('COUNT: EXACT BINOMIAL',
  'WORDS: EXACTLY / AT MOST / AT LEAST k SUCCESSES IN n TRIALS. FIXED n, TWO OUTCOMES, SAME p, INDEPENDENT. P(X=k)=nCk*p^k*(1-p)^(n-k). HOME 2. FOR p-hat CUTOFF q, X=n*p-hat; PRESERVE STRICT / INCLUDED ENDPOINTS WITHOUT ROUNDING n*q.'),
 ('WITHOUT REPLACEMENT',
  'WORDS: DRAW FROM A FINITE BOX / GROUP WITHOUT RETURNING ITEMS. X=SUCCESSES; P(X=k)=C(K,k)*C(N-K,n-k)/C(N,n). N=POPULATION; K=TOTAL SUCCESSES; n=DRAWS. HOME 2 > WITHOUT REPLACEMENT (QUESTION-WORDS MENU). DO NOT TREAT DEPENDENT DRAWS AS EXACT BINOMIAL. SMALL SAMPLE FRACTIONS CAN SUPPORT AN APPROXIMATION.'),
 ('PAIRED / BEFORE-AFTER MEAN CI',
  'SAME PEOPLE TWICE OR MATCHED PAIRS: COMPUTE ONE DIFFERENCE PER PAIR, WITH A CONSISTENT DIRECTION. d-bar +/- t* s_d/sqrt(n); df=n-1; n=NUMBER OF PAIRS. HOME 11 > 3 WITH THE DIFFERENCE LIST OR ITS SUMMARY. DO NOT USE THE INDEPENDENT TWO-MEAN FORMULA.'),
 ('TWO INDEPENDENT MEAN CI',
  'COMPARE TWO INDEPENDENT GROUP AVERAGES: (x-bar1-x-bar2) +/- t* sqrt(s1^2/n1+s2^2/n2). USE WELCH df; NOT AUTOMATICALLY n1+n2-2. HOME 11 > 5 COMPUTES SE AND df. CHECK RANDOMNESS, INDEPENDENT GROUPS AND EACH GROUP SHAPE. KEEP GROUP 1 MINUS GROUP 2 CONSISTENT.'),
 ('TWO PROPORTION CI',
  'COMPARE TWO INDEPENDENT GROUP PERCENTS: (p-hat1-p-hat2) +/- z* sqrt(p-hat1*(1-p-hat1)/n1+p-hat2*(1-p-hat2)/n2). HOME 11 > 4. CHECK SUCCESS / FAILURE COUNTS IN EACH GROUP. THIS CI USES SEPARATE SAMPLE PROPORTIONS, NOT A POOLED TEST PROPORTION.'),
 ('CRITICAL VALUE / MARGIN / ENDS',
  'CRITICAL VALUE: CONFIDENCE OR TAIL AREA -> z* (HOME 13), OR t* WITH df (HOME 14). E=abs(CRITICAL)*SE. FROM TWO-SIDED INTERVAL [L,U]: POINT ESTIMATE=(L+U)/2; E=(U-L)/2. FROM ESTIMATE AND E: ENDS=ESTIMATE +/- E (HOME 11 > 7). CONFIDENCE ALONE DOES NOT GIVE A POINT ESTIMATE OR E.')
)

def formula_menu():
    while True:
        key=c.menu('EXAM > WHICH FORMULA?',[(str(i+1),label) for i,(label,text) in enumerate(FORMULAS)])
        if key=='0': return
        label,text=FORMULAS[int(key)-1]
        c.view(label,[text])

def rules_menu():
    while True:
        key=c.menu('STUDY > RULES / FORMULAS',[(str(i+1),label) for i,(label,text) in enumerate(RULES)])
        if key=='0': return
        label,text=RULES[int(key)-1]
        c.view(label,[text])
